    excluded = {"date": date(2026, 9, 30), "km": 8.0}
    html = render_rides_page([included, excluded], TODAY)
    assert "2026-10-01" in html
    assert "2026-09-30" not in html


def test_lists_a_ride_dated_today_on_the_page():
